		}
		mean /= float64(len(src))
		var variance float64
		for _, v := range src {
			d := float64(v) - mean
			variance += d * d
		}
		variance /= float64(len(src))
		inv := 1 / math.Sqrt(variance+h.FinalEps)
		for i, v := range src {
			dst[i] = float32((float64(v)-mean)*inv) * (1 + scale[i])
		}
	})
	return h.FinalLin.Apply(normed)
}

