3	import (
4		"encoding/binary"
5		"encoding/json"
6		"math"
7		"os"
8		"path/filepath"
9		"testing"
10	)
11	
12	// The reference is reference/dump_zimage.py, which drives the checkpoint's own
13	// FlowMatchEulerDiscreteScheduler the way the pipeline does:
14	//
15	//	.venv/bin/python reference/dump_zimage.py
16	const (
17		refDir       = "../../reference/out/zimage"
18		runDir       = "../../reference/out/zimagerun"
19		schedulerDir = "../../models/Z-Image-Turbo/scheduler"
20	)
21	
22	type manifest struct {
23		dir   string
24		Steps int `json:"steps"`
25		// Size and Prompt are dump_zimage_run.py's; dump_zimage.py carries
26		// neither, which is how a test says which dump it wants.
27		Size    int    `json:"size"`
28		Prompt  string `json:"prompt"`
29		Tensors map[string]struct {
30			Shape []int `json:"shape"`
31			Count int   `json:"count"`
32		} `json:"tensors"`
33	}
34	
35	func loadManifest(t *testing.T, dir string) *manifest {
36		t.Helper()
37		buf, err := os.ReadFile(filepath.Join(dir, "manifest.json"))
38		if err != nil {
39			t.Skipf("no reference dump in %s (%v); run reference/dump_zimage.py or dump_zimage_run.py", dir, err)
40		}
41		var m manifest
42		if err := json.Unmarshal(buf, &m); err != nil {
43			t.Fatal(err)
44		}
45		m.dir = dir
46		return &m
47	}
48	
49	func loadRef(t *testing.T, m *manifest, name string) []float32 {
50		t.Helper()
51		meta, ok := m.Tensors[name]
52		if !ok {
53			t.Fatalf("reference has no tensor %q", name)
54		}
55		raw, err := os.ReadFile(filepath.Join(m.dir, name+".bin"))
56		if err != nil {
57			t.Fatal(err)
58		}
59		if len(raw) != meta.Count*4 {
60			t.Fatalf("%s: %d bytes for %d float32", name, len(raw), meta.Count)
61		}
62		out := make([]float32, meta.Count)
63		for i := range out {
64			out[i] = math.Float32frombits(binary.LittleEndian.Uint32(raw[i*4:]))
65		}
66		return out
67	}
68	
69	// schedTol is loose next to the rest of the pipeline's bounds because these
70	// are absolute comparisons of numbers of order 1 and 1000 rather than
71	// RMS-normalised tensors: diffusers builds the schedule in float32 and this
72	// builds it in float64, so the last bit of a timestep differs.
73	const schedTol = 1e-4
74	
75	func newSchedule(t *testing.T, steps int) *FlowMatchEuler {
76		t.Helper()
77		cfg, err := LoadSchedulerConfig(schedulerDir)
78		if err != nil {
79			t.Skipf("no scheduler config at %s (%v)", schedulerDir, err)
80		}
81		s, err := NewFlowMatchEuler(steps, cfg)
82		if err != nil {
83			t.Fatal(err)
84		}
85		return s
86	}
87	
88	// TestSchedule checks the eight sigmas, their timesteps and the conditioning
89	// value each step sends the transformer. The schedule is eight numbers that
90	// decide what every one of the 8 x 34 block runs is conditioned on, so a wrong
91	// one is a worse image and nothing else -- there is no shape to catch it.
92	func TestSchedule(t *testing.T) {
93		m := loadManifest(t, refDir)
94		s := newSchedule(t, m.Steps)
95	
96		for _, c := range []struct {
97			name string
98			got  []float64
99		}{
100			{"sigmas", s.Sigmas},
101			{"timesteps", s.Timesteps},
102			{"model_t", modelT(s)},
103		} {
104			want := loadRef(t, m, c.name)
105			if len(c.got) != len(want) {
106				t.Fatalf("%s: %d values, want %d", c.name, len(c.got), len(want))
107			}
108			var worst float64
109			for i := range want {
110				scale := math.Max(math.Abs(float64(want[i])), 1)
111				if d := math.Abs(c.got[i]-float64(want[i])) / scale; d > worst {
112					worst = d
113				}
114			}
115			if worst > schedTol {
116				t.Errorf("%s: worst relative difference %.3g\n got  %v\n want %v", c.name, worst, c.got, want)
117				continue
118			}
119			t.Logf("%-10s worst %.2g", c.name, worst)
120		}
121	
122		if s.Sigmas[len(s.Sigmas)-1] != 0 {
123			t.Errorf("the schedule does not terminate at sigma 0: %v", s.Sigmas)
124		}
125	}
126	
127	func modelT(s *FlowMatchEuler) []float64 {
128		out := make([]float64, s.Steps())
129		for i := range out {
130			out[i] = s.ModelT(i)
131		}
132		return out
133	}
134	
135	// TestStep checks the Euler update itself against the scheduler's own.
136	func TestStep(t *testing.T) {
137		m := loadManifest(t, refDir)
138		s := newSchedule(t, m.Steps)
139	
140		sample := loadRef(t, m, "step_sample")
141		out := loadRef(t, m, "step_model_out")
142		want := loadRef(t, m, "step_result")
143	
144		got := append([]float32(nil), sample...)
145		if err := s.Step(0, got, out); err != nil {
146			t.Fatal(err)
147		}
148		var worst float64
149		for i := range want {
150			if d := math.Abs(float64(got[i] - want[i])); d > worst {
151				worst = d
152			}
153		}
154		if worst > schedTol {
155			t.Fatalf("step: worst absolute difference %.3g", worst)
156		}
157		t.Logf("step       worst %.2g", worst)
158	
159		// The negative control: the step with the shifted schedule's *unshifted*
160		// sigmas, which is the mistake a scheduler config invites -- the shift is
161		// in the config and nothing about a sigma says whether it was applied.
162		raw := &FlowMatchEuler{Sigmas: make([]float64, len(s.Sigmas)), TrainTimesteps: s.TrainTimesteps,
163			Timesteps: s.Timesteps, Shift: 1}
164		for i := range raw.Sigmas {
165			raw.Sigmas[i] = s.Sigmas[i] / (s.Shift - (s.Shift-1)*s.Sigmas[i])
166		}
167		broken := append([]float32(nil), sample...)
168		if err := raw.Step(0, broken, out); err != nil {
169			t.Fatal(err)
170		}
171		var brokenWorst float64
172		for i := range want {
173			if d := math.Abs(float64(broken[i] - want[i])); d > brokenWorst {
174				brokenWorst = d
175			}
176		}
177		if brokenWorst <= schedTol {
178			t.Errorf("the unshifted schedule is inside the bound (%.3g); the test would not catch it", brokenWorst)
179		}
180		t.Logf("unshifted  worst %.2g = %.0fx the bound", brokenWorst, brokenWorst/schedTol)
181	}
182	
183	// TestStepCount checks the schedule at the lengths the CLI allows, since the
184	// linspace degenerates at one step and the terminal zero is what carries it.
185	func TestStepCount(t *testing.T) {
186		for _, n := range []int{1, 2, 4, 8, 20, 50} {
187			s := newSchedule(t, n)
188			if s.Steps() != n || len(s.Sigmas) != n+1 {
189				t.Fatalf("%d steps: %d timesteps, %d sigmas", n, s.Steps(), len(s.Sigmas))
190			}
191			for i := 0; i < n; i++ {
192				if s.Sigmas[i] <= s.Sigmas[i+1] {
193					t.Fatalf("%d steps: sigma %d (%g) does not exceed sigma %d (%g)", n, i, s.Sigmas[i], i+1, s.Sigmas[i+1])
194				}
195			}
196			if s.Sigmas[0] != 1 {
197				t.Errorf("%d steps: starts at sigma %g, want 1", n, s.Sigmas[0])
198			}
199		}
200	}

