3	import (
4		"fmt"
5		"math"
6		"testing"
7	
8		"strix-halo-vulkan/vk"
9	)
10	
11	// Stage 6's end-to-end check, and the only one that can exist for what this
12	// stage adds. The head, the blocks, the scheduler and the VAE each have their
13	// own oracle; "the four of them run in the right order with the right
14	// conventions" is a claim about the *composition*, and nothing below it can
15	// test that.
16	//
17	// The reference is reference/dump_zimage_run.py, which runs diffusers'
18	// ZImagePipeline in fp32 on the CPU from the same initial latent:
19	//
20	//	.venv/bin/python reference/dump_zimage_run.py --size 256
21	//
22	// It is affordable because the composition does not know how big the image is.
23	// At 256x256 the unified sequence is 288 tokens rather than 4128, so diffusers
24	// walks all eight steps on the CPU in half a minute and this walks them in two
25	// seconds.
26	
27	const modelDir = "../../models/Z-Image-Turbo"
28	
29	// strixHaloDeviceID picks the iGPU when the machine also enumerates something
30	// else; devs[0] otherwise.
31	const strixHaloDeviceID = 0x1586
32	
33	func newTestDevice(t *testing.T) (*vk.Device, func()) {
34		t.Helper()
35		inst, err := vk.NewInstance("pipeline-test")
36		if err != nil {
37			t.Skipf("no Vulkan instance (%v)", err)
38		}
39		devs, err := inst.PhysicalDevices()
40		if err != nil || len(devs) == 0 {
41			inst.Destroy()
42			t.Skipf("no Vulkan device (%v)", err)
43		}
44		phys := &devs[0]
45		for i := range devs {
46			if devs[i].DeviceID == strixHaloDeviceID {
47				phys = &devs[i]
48			}
49		}
50		qf, err := phys.ComputeQueueFamily()
51		if err != nil {
52			inst.Destroy()
53			t.Skipf("no compute queue (%v)", err)
54		}
55		sgs, err := phys.SubgroupSizeControl()
56		if err != nil {
57			inst.Destroy()
58			t.Fatal(err)
59		}
60		dev, err := vk.NewDevice(phys, qf, vk.DeviceFeatures{
61			Float16: true, CoopMatrix: true, SubgroupSizeControl: sgs.Supported,
62		})
63		if err != nil {
64			inst.Destroy()
65			t.Skipf("no fp16 cooperative-matrix device (%v)", err)
66		}
67		t.Logf("device: %s", phys.Name)
68		return dev, func() { dev.Destroy(); inst.Destroy() }
69	}
70	
71	// relL2 is the whole-tensor error this stage is judged by, rather than the
72	// max-over-RMS the earlier stages use.
73	//
74	// The reason is the object: a denoising trajectory is chaotic, so a single
75	// element of the last latent can be far from the reference's while the image
76	// is the same image. What has to be bounded is the tensor as a whole, and
77	// relative L2 is that -- it is also what says how much of the *signal* the
78	// difference is, which max-over-RMS does not.
79	func relL2(got, want []float32) float64 {
80		var num, den float64
81		for i := range want {
82			d := float64(got[i]) - float64(want[i])
83			num += d * d
84			den += float64(want[i]) * float64(want[i])
85		}
86		return math.Sqrt(num / den)
87	}
88	
89	// TestPipelineAgainstDiffusers walks the eight steps beside diffusers'.
90	//
91	// Two bounds, and they say different things. The per-step latent bound is the
92	// fp16 chain's error compounding through the loop -- it starts at 1.4e-4 and
93	// the feedback multiplies it by about 1.6 a step -- and what it is really
94	// checking is that the growth is *geometric from rounding* rather than a
95	// constant offset from a convention. The image bound is the one that matters:
96	// after the VAE the two decodes are the same picture.
97	func TestPipelineAgainstDiffusers(t *testing.T) {
98		m := loadManifest(t, runDir)
99		if m.Size == 0 {
100			t.Skipf("%s is not a dump_zimage_run.py manifest", runDir)
101		}
102		dev, done := newTestDevice(t)
103		defer done()
104	
105		p, err := New(dev, Options{Model: modelDir, Width: m.Size, Height: m.Size, Steps: m.Steps})
106		if err != nil {
107			t.Skipf("cannot build the pipeline (%v)", err)
108		}
109		defer p.Destroy()
110	
111		init := loadRef(t, m, "latents_init")
112		latents := append([]float32(nil), init...)
113	
114		// The bound per step. The measured sequence is 1.4e-4 rising to 2.1e-2;
115		// 6e-2 leaves room for the run-to-run variation a GPU reduction order has
116		// and is still 16x below where the last step's control lands.
117		const stepTol = 6e-2
118		var steps []float64
119		img, tm, err := p.GenerateFrom(m.Prompt, latents, func(s Step) {
120			steps = append(steps, relL2(s.Latents, loadRef(t, m, fmt.Sprintf("latents_%d", s.Index))))
121		})
122		if err != nil {
123			t.Fatal(err)
124		}
125		for i, e := range steps {
126			if e > stepTol {
127				t.Errorf("step %d: relative L2 %.3g > %.0e", i, e, stepTol)
128			}
129		}
130		t.Logf("%d tokens, %d caption rows, %d unified; per-step relative L2 %s",
131			tm.Tokens, tm.CapTotal, tm.Unified, fmtErrs(steps))
132	
133		if e := relL2(latents, loadRef(t, m, "latents_final")); e > stepTol {
134			t.Errorf("final latent: relative L2 %.3g > %.0e", e, stepTol)
135		}
136	
137		// The image. 3e-2 is where the measurement lands and it is a bound on a
138		// tensor in [-1, 1], so it is about a quarter of an 8-bit level.
139		const imageTol = 3e-2
140		want := loadRef(t, m, "image")
141		if len(img.Data) != len(want) {
142			t.Fatalf("decoded %s, reference has %d values", img, len(want))
143		}
144		e := relL2(img.Data, want)
145		if e > imageTol {
146			t.Errorf("image: relative L2 %.3g > %.0e", e, imageTol)
147		}
148		t.Logf("image %dx%d: relative L2 %.3g, max abs %.3g", img.W, img.H, e, maxAbs(img.Data, want))
149	}
150	
151	// TestPipelineDetectsErrors is the negative control. Each case breaks one
152	// thing the composition gets to decide and asserts the break is caught: the
153	// direction the schedule integrates in, whether the context refiners ran at
154	// all, and where the caption sits on the rotary axis.
155	//
156	// Without it the test above proves only that the pipeline runs, and each of
157	// these produces an image.
158	func TestPipelineDetectsErrors(t *testing.T) {
159		m := loadManifest(t, runDir)
160		if m.Size == 0 {
161			t.Skipf("%s is not a dump_zimage_run.py manifest", runDir)
162		}
163		dev, done := newTestDevice(t)
164		defer done()
165	
166		p, err := New(dev, Options{Model: modelDir, Width: m.Size, Height: m.Size, Steps: m.Steps})
167		if err != nil {
168			t.Skipf("cannot build the pipeline (%v)", err)
169		}
170		defer p.Destroy()
171	
172		init := loadRef(t, m, "latents_init")
173		wantLatent := loadRef(t, m, "latents_final")
174		wantImage := loadRef(t, m, "image")
175	
176		const stepTol, imageTol = 6e-2, 3e-2
177		for _, c := range []struct {
178			name string
179			ctl  controls
180		}{
181			{"model output not negated", controls{noNegate: true}},
182			{"caption not refined", controls{staleCaption: true}},
183			{"caption positions from 0", controls{capPosFromZero: true}},
184		} {
185			p.ctl = c.ctl
186			latents := append([]float32(nil), init...)
187			img, _, err := p.GenerateFrom(m.Prompt, latents, nil)
188			p.ctl = controls{}
189			if err != nil {
190				t.Fatalf("%s: %v", c.name, err)
191			}
192			le, ie := relL2(latents, wantLatent), relL2(img.Data, wantImage)
193			if le <= stepTol || ie <= imageTol {
194				t.Errorf("%s: latent %.3g, image %.3g -- inside the bounds, the test would not catch it", c.name, le, ie)
195				continue
196			}
197			t.Logf("%-26s latent %.3g = %.0fx the bound, image %.3g = %.0fx",
198				c.name, le, le/stepTol, ie, ie/imageTol)
199		}
200	}
201	
202	func maxAbs(got, want []float32) float64 {
203		var m float64
204		for i := range want {
205			if d := math.Abs(float64(got[i]) - float64(want[i])); d > m {
206				m = d
207			}
208		}
209		return m
210	}
211	
212	func fmtErrs(v []float64) string {
213		s := ""
214		for _, e := range v {
215			s += fmt.Sprintf("%.2g ", e)
216		}
217		return s
218	}
